#include "cantidad.hpp"
#include <iostream>

int main() {
    const int datos[] = {-1, 0, 20, 21};
    const bool esperados[] = {false, true, true, false};
    bool todo_bien = true;
    for (int i = 0; i < 4; ++i) {
        const bool obtenido = cantidad_admitida(datos[i]);
        const bool coincide = obtenido == esperados[i];
        std::cout << "dato=" << datos[i]
                  << " esperado=" << esperados[i]
                  << " obtenido=" << obtenido
                  << (coincide ? " OK\n" : " ERROR\n");
        todo_bien = todo_bien && coincide;
    }
    std::cout << (todo_bien ? "Bateria: OK\n" : "Bateria: ERROR\n");
    return todo_bien ? 0 : 1;
}

